aggregate_kpis AS (
SELECT 
    prac_code,prac_name,region,PK_Patient_ID,
    SUM(MiComor) AS MiComor,
    SUM(ChronicObstructivePulmonaryComor) AS ChronicObstructivePulmonaryComor,
    SUM(CancerComor) AS CancerComor,
    SUM(CardiovascularComor) AS CardiovascularComor,
    SUM(HeartFailureComor) AS HeartFailureComor,
    SUM(ConnectiveTissueComor) AS ConnectiveTissueComor,
    SUM(DementiaComor) AS DementiaComor,
    SUM(DiabetesComor) AS DiabetesComor,
    SUM(DiabetesComplicationsComor) AS DiabetesComplicationsComor,
    SUM(HemiplegiaComor) AS HemiplegiaComor,
    SUM(HivComor) AS HivComor,
    SUM(MetastaticCancerComor) AS MetastaticCancerComor,
    SUM(MildLiverComor) AS MildLiverComor,
    SUM(ModSevereLiverComor) AS ModSevereLiverComor,
    SUM(ModSevereRenalComor) AS ModSevereRenalComor,
    SUM(PepticUlcerComor) AS PepticUlcerComor,
    SUM(PeripheralVascularComor) AS PeripheralVascularComor
FROM union_kpis
GROUP BY prac_code,prac_name,region,PK_Patient_ID 
),
per_patient_cci AS (
SELECT prac_code,prac_name,region,PK_Patient_ID,
            2 * CancerComor +
            1 * CardiovascularComor +
            1 * ChronicObstructivePulmonaryComor +
            1 * HeartFailureComor +
            1 * ConnectiveTissueComor +
            1 * DementiaComor +
            1 * DiabetesComor +
            2 * DiabetesComplicationsComor +
            2 * HemiplegiaComor +
            6 * HivComor +
            6 * MetastaticCancerComor +
            1 * MildLiverComor +
            3 * ModSevereLiverComor +
            2 * ModSevereRenalComor +
            1 * MiComor +
            1 * PepticUlcerComor +
            1 * PeripheralVascularComor AS cci_per_patient
FROM
    aggregate_kpis
),
missing_patient AS (
SELECT
  PK_Patient_ID,
  OrganisationCode AS prac_code,
  B.Name AS prac_name,
  Region AS region,
  DATEDIFF(YEAR, dob, '2024-05-01') 
    - CASE 
        WHEN MONTH(dob) > 5 OR (MONTH(dob) = 5 AND DAY(dob) > 1) THEN 1 
        ELSE 0 
      END AS age
FROM 
    [BRIT].[Patient] A 
    INNER JOIN [BRIT].[Reference_GP_Practice] B 
    ON B.PK_Reference_GP_Practice_ID=A.FK_Reference_GP_Practice_ID 
    INNER JOIN [BRIT].[patient_link] pl 
    ON A.FK_Patient_Link_ID = pl.PK_Patient_Link_ID
    INNER JOIN BRIT.GP_Events med  
    ON med.FK_Patient_Link_ID = pl.PK_Patient_Link_ID
    INNER JOIN BRIT.Reference_SnomedCT snomed
    ON snomed.PK_Reference_SnomedCT_ID = med.FK_Reference_SnomedCT_ID


),
final_per_patient_cci AS (
SELECT prac_code,prac_name,region,PK_Patient_ID,cci_per_patient FROM per_patient_cci
UNION 
SELECT prac_code,prac_name,region,PK_Patient_ID,0 AS cci_per_patient FROM missing_patient where PK_Patient_ID not in (select distinct PK_Patient_ID from per_patient_cci)
),
category_cci_per_patient AS (
SELECT 
    prac_code,
    prac_name,
    region,
    PK_Patient_ID,
    cci_per_patient AS CCI_Score,
        CASE WHEN cci_per_patient = 0 THEN 1 ELSE 0 END AS CciVeryLow,
        CASE WHEN cci_per_patient = 1 THEN 1 ELSE 0 END AS CciLow,
        CASE WHEN cci_per_patient = 2 THEN 1 ELSE 0 END AS CciMedium,
        CASE WHEN cci_per_patient IN (3,4) THEN 1 ELSE 0 END AS CciHigh,
        CASE WHEN cci_per_patient >= 5 THEN 1 ELSE 0 END AS CciVeryHigh
    FROM final_per_patient_cci
)
SELECT
    PK_Patient_ID,
    prac_code,
    prac_name,
    region,
    CCI_Score,
    CciVeryLow, 
    CciLow,
    CciMedium,
    CciHigh,
    CciVeryHigh
INTO PerPatientCCIScore
FROM category_cci_per_patient;
